 26	pub(crate) enum SenderSource {
 27	    /// A same-node sender whose batches the engine parked on the GPU.
 28	    LocalParked {
 29	        /// Sender output names, which become the input stream's column names.
 30	        names: Vec<String>,
 31	        /// Where the engine parked this sender's batches.
 32	        slot: SenderSlot,
 33	    },
 34	    /// A remote sender whose packed batches were nixl-WRITTEN into this CN's staging arena and
 35	    /// announced over `transmit_packed`. Counts toward readiness only once `closed`.
 36	    Remote {
 37	        /// Sender output names carried on every `transmit_packed` frame (first frame wins,
 38	        /// later frames must match).
 39	        names: Vec<String>,
 40	        /// Sender ordinal, needed to `close_input` the engine stream it feeds.
 41	        sender_id: i32,
 42	        /// Batches staged in arrival (sequence) order; the engine releases each lease after
 43	        /// pushing it.
 44	        batches: Vec<StagedBatch>,
 45	        /// The sender announced eos; no more frames may follow.
 46	        closed: bool,
 47	    },
 48	}
