 50	impl SenderSource {
 51	    /// The sender's output column names, whichever side of the wire it sits on.
 52	    pub(crate) fn names(&self) -> &[String] {
 53	        match self {
 54	            Self::LocalParked { names, .. } | Self::Remote { names, .. } => names,
 55	        }
 56	    }
 57	
 58	    /// Whether this sender has finished producing (a parked local sender always has).
 59	    fn is_complete(&self) -> bool {
 60	        match self {
 61	            Self::LocalParked { .. } => true,
 62	            Self::Remote { closed, .. } => *closed,
 63	        }
 64	    }
 65	}
