    42	struct stream_input_spec {
    43	  std::vector<std::string> names;
    44	  duckdb::vector<sirius::logical_type> types;
    45	  /// Sender-set EOS: stream ends only once all have closed.
    46	  std::set<sender_id_t> expected_senders;
    47	  /// Optional caller-declared row count, forwarded to the bind catalog so DuckDB's optimizer
    48	  /// can size the stream (see stream_input_binding::estimated_rows). nullopt = undeclared.
    49	  std::optional<std::uint64_t> estimated_rows;
