    71	/// Owns repos/engine/session for one fragment.
    72	/// Repositories escape data_repository_manager_ cleanup (survive the query window).
    73	/// Engine owns the plan so the sink stays pullable after run().
    74	class streaming_fragment {
    75	 public:
    76	  /// Validates the spec and creates one repository per declared stream.
    77	  /// @throws sirius::invalid_input_exception when plan_source is unset, outputs empty, N>1
    78	  ///         without partitioning, or on a duplicate output id.
    79	  streaming_fragment(duckdb::ClientContext& context, fragment_spec spec);
    80	
    81	  /// Clears this fragment's declarations from the connection's stream_bind_catalog.
    82	  ~streaming_fragment();
    83	
    84	  streaming_fragment(const streaming_fragment&)            = delete;
    85	  streaming_fragment& operator=(const streaming_fragment&) = delete;
    86	
    87	  /// Declare inputs, lower to STREAMING_SOURCE/SINK, register with session. Separate from
    88	  /// run() so callers can push first.
    89	  /// @throws sirius::invalid_input_exception when already built, no catalog, null plan, or a
    90	  ///         declared input the plan never reads.
    91	  /// @throws whatever the plan source, binder, or plan generator raises.
    92	  void build(sirius::query_id_t query_id);
    93	
    94	  /// Submit and block. Shared query window (don't open a second StandaloneQueryScope between
    95	  /// build and run).
    96	  /// @throws sirius::invalid_input_exception when build() has not run.
    97	  /// @throws whatever the engine's execution raises.
    98	  void run();
    99	
   100	  [[nodiscard]] stream_session& session() { return _session; }
   101	
   102	  [[nodiscard]] sirius::sirius_engine& engine() { return *_engine; }
   103	
   104	  /// Physical output column types of the plan root (set during build()).
   105	  /// Used by relay steps to validate schema agreement before any data moves.
   106	  /// @throws sirius::invalid_input_exception when build() has not run.
   107	  [[nodiscard]] const duckdb::vector<sirius::logical_type>& sink_types() const;
   108	
   109	  /// @throws sirius::invalid_input_exception when `id` is not a declared input stream.
   110	  [[nodiscard]] const std::shared_ptr<cucascade::shared_data_repository>& input_repository(
   111	    stream_id_t id) const;
   112	
   113	  /// @throws sirius::invalid_input_exception when `id` is not a declared output stream.
   114	  [[nodiscard]] const std::shared_ptr<cucascade::shared_data_repository>& output_repository(
   115	    stream_id_t id) const;
   116	
   117	 private:
   118	  duckdb::ClientContext& _context;
   119	  fragment_spec _spec;
   120	
   121	  // Declaration order IS the lifetime contract (destroyed in reverse): repositories outlive
   122	  // the engine, the engine owns the plan, and the session (borrowing operators) is torn down first.
   123	  std::map<stream_id_t, std::shared_ptr<cucascade::shared_data_repository>> _input_repos;
   124	  std::map<stream_id_t, std::shared_ptr<cucascade::shared_data_repository>> _output_repos;
   125	  std::unique_ptr<sirius::sirius_interface> _iface;
   126	  std::unique_ptr<sirius::sirius_engine> _engine;
   127	  stream_session _session;
   128	
   129	  bool _built{false};
   130	  duckdb::vector<sirius::logical_type> _sink_types;
   131	};
