1717	/// Translates a `HASH_JOIN_NODE` into a Substrait join relation.
1718	///
1719	/// StarRocks children are `[probe (left), build (right)]`; the Substrait join condition is
1720	/// evaluated over the concatenated left-then-right row, which is exactly how
1721	/// `slot_global_index` resolves slots against the combined layout.
1722	fn translate_hash_join(
1723	    node: &TPlanNode,
1724	    children: Vec<TranslatedRel>,
1725	    ctx: &mut PlanContext<'_>,
1726	) -> Result<TranslatedRel> {
1727	    expect_children(node, &children, 2)?;
1728	    let join = node
1729	        .hash_join_node
1730	        .as_ref()
1731	        .ok_or(TranslateError::MissingField {
1732	            context: "HASH_JOIN_NODE",
1733	            field: "hash_join_node",
1734	        })?;
1735	    let mut children = children.into_iter();
1736	    let left = children.next().unwrap();
1737	    let right = children.next().unwrap();
1738	    refuse_carried_join_child(node, &left)?;
1739	    refuse_carried_join_child(node, &right)?;
1740	
1741	    // Validated before the conjuncts so an unsupported op is reported as such, rather than as
1742	    // the missing conjuncts a folded-away predicate arrives with.
1743	    let (join_type, output) = match join.join_op {
1744	        TJoinOp::INNER_JOIN => (join_rel::JoinType::Inner, JoinOutput::Both),
1745	        TJoinOp::LEFT_OUTER_JOIN => (join_rel::JoinType::Left, JoinOutput::Both),
1746	        TJoinOp::RIGHT_OUTER_JOIN => (join_rel::JoinType::Right, JoinOutput::Both),
1747	        TJoinOp::FULL_OUTER_JOIN => (join_rel::JoinType::Outer, JoinOutput::Both),
1748	        TJoinOp::LEFT_SEMI_JOIN => (join_rel::JoinType::LeftSemi, JoinOutput::Left),
1749	        TJoinOp::LEFT_ANTI_JOIN => (join_rel::JoinType::Left, JoinOutput::LeftAnti),
1750	        TJoinOp::RIGHT_ANTI_JOIN => (join_rel::JoinType::Right, JoinOutput::RightAnti),
1751	        TJoinOp::NULL_AWARE_LEFT_ANTI_JOIN => {
1752	            (join_rel::JoinType::LeftMark, JoinOutput::NullAwareLeftAnti)
1753	        }
1754	        _ => {
1755	            return Err(TranslateError::UnsupportedPlanNode {
1756	                node_id: node.node_id,
1757	                node_type: node.node_type,
1758	                reason: "hash join type is unsupported",
1759	            });
1760	        }
1761	    };
1762	
1763	    let combined_tuples = [left.row_tuples.as_slice(), right.row_tuples.as_slice()].concat();
1764	    let mut conditions = Vec::new();
1765	    let mut first_equality = None;
1766	    for eq in &join.eq_join_conjuncts {
1767	        if let Some(opcode) = eq.opcode
1768	            && opcode != TExprOpcode::EQ
1769	        {
1770	            return Err(TranslateError::UnsupportedPlanNode {
1771	                node_id: node.node_id,
1772	                node_type: node.node_type,
1773	                reason: "only plain equality join conjuncts are supported",
1774	            });
1775	        }
1776	        let mut expr_ctx = ctx.expr_context(&combined_tuples);
1777	        let left_expr = eq.left.translate(&mut expr_ctx)?;
1778	        let mut expr_ctx = ctx.expr_context(&combined_tuples);
1779	        let right_expr = eq.right.translate(&mut expr_ctx)?;
1780	        if first_equality.is_none() {
1781	            first_equality = Some((left_expr.clone(), right_expr.clone()));
1782	        }
1783	        let anchor = ctx.registry.register_function(URN_COMPARISON, "equal");
1784	        conditions.push(expr_translator::scalar_function(
1785	            anchor,
1786	            vec![left_expr, right_expr],
1787	            crate::type_mapper::bool_type(),
1788	        ));
1789	    }
1790	    for expr in join.other_join_conjuncts.as_deref().unwrap_or_default() {
