1897	/// Translates an inner/cross `NESTLOOP_JOIN_NODE` into an equality join on synthetic constants.
1898	/// This preserves Cartesian-product semantics without requiring a GPU cross-product operator.
1899	fn translate_nestloop_join(
1900	    node: &TPlanNode,
1901	    children: Vec<TranslatedRel>,
1902	    ctx: &mut PlanContext<'_>,
1903	) -> Result<TranslatedRel> {
