1913	        None | Some(TJoinOp::CROSS_JOIN) | Some(TJoinOp::INNER_JOIN) => {}
1914	        Some(_) => {
1915	            return Err(TranslateError::UnsupportedPlanNode {
1916	                node_id: node.node_id,
1917	                node_type: node.node_type,
1918	                reason: "only inner/cross nested-loop joins are supported",
1919	            });
1920	        }
1921	    }
1922	    // Lowering a Cartesian product to a constant-key equality join replaced the rejection that
1923	    // used to refuse it ("the GPU physical planner has no cross-product operator"), so this shape
