1952	                left: Some(Box::new(left.rel)),
1953	                right: Some(Box::new(right.rel)),
1954	                expression: Some(Box::new(condition)),
1955	                r#type: join_rel::JoinType::Inner as i32,
1956	                ..Default::default()
