638	void Fragment::build(const std::string& substrait_plan)
639	{
640	  impl_->require_not_built("build");
641	
642	  // Transaction must be open for: type-name parsing (catalog lookup) and CREATE VIEW.
643	  // It must be committed before QueryBeginStandalone acquires the lifecycle mutex.
644	  impl_->ctx.conn->BeginTransaction();
645	  impl_->transaction_open = true;
646	  std::map<sirius::exec::stream_id_t, sirius::exec::stream_input_spec> resolved;
647	  try {
648	    resolved               = impl_->resolve_inputs();
649	    impl_->resolved_inputs = resolved;
650	    impl_->declare_streams(resolved);
651	    impl_->create_stream_views();
652	    impl_->ctx.conn->Commit();
653	    impl_->transaction_open = false;
654	  } catch (...) {
655	    impl_->end_lifecycle();
656	    throw;
657	  }
658	
659	  // Open lifecycle (StandaloneQueryScope acquires the slot and begins the window).
660	  auto& client     = *impl_->ctx.conn->context;
661	  impl_->lifecycle = std::make_unique<duckdb::SiriusContext::StandaloneQueryScope>(
662	    *impl_->ctx.context, client, impl_->query_label);
663	
664	  try {
665	    // A routing mode needs at least two destinations to mean anything: with 0 or 1 declared
666	    // outputs every row goes to the same place either way, so accepting it here would hide a
667	    // fan-out that never happened. Checked before the is_result()/else split below so it also
668	    // catches a partition mode declared on a 0-output result fragment, not just a 1-output one.
669	    if (impl_->outputs.size() <= 1 &&
670	        (impl_->broadcast_outputs || !impl_->hash_key_columns.empty())) {
671	      throw sirius::invalid_input_exception(
672	        "Fragment: a partition mode was declared but the fragment has " +
673	        std::to_string(impl_->outputs.size()) +
674	        " output stream(s); routing needs at least two destinations");
675	    }
676	
677	    if (impl_->is_result()) {
678	      // A result fragment takes the single-shot execution path; its leaves may be streaming
679	      // sources built from the bind catalog.
680	      auto lowered       = lower_substrait(*impl_->ctx.conn, substrait_plan);
681	      auto physical_plan = sirius::planner::sirius_physical_plan_generator(client).create_plan(
682	        std::move(lowered.plan));
683	      impl_->result_plan = duckdb::make_shared_ptr<sirius::sirius_prepared_statement_data>(
684	        std::move(lowered.prepared), std::move(physical_plan));
685	
686	      for (const auto& [id, _] : impl_->inputs) {
687	        auto* built = impl_->ctx.stream_catalog->get(id).built;
688	        if (built == nullptr) {
689	          throw sirius::invalid_input_exception("Fragment: input stream " + std::to_string(id) +
690	                                                " was declared but the plan does not read it");
691	        }
692	        impl_->result_session.add_source(id, *built);
693	      }
694	    } else {
695	      sirius::exec::fragment_spec spec;
696	      spec.plan_source = [plan = substrait_plan, conn = impl_->ctx.conn.get()](
697	                           duckdb::ClientContext&) { return lower_substrait(*conn, plan).plan; };
698	      spec.inputs        = std::move(resolved);
699	      spec.outputs       = impl_->outputs;
700	      spec.query_label   = impl_->query_label;
701	      spec.session_label = impl_->session_label;
702	
703	      if (impl_->broadcast_outputs && impl_->outputs.size() > 1) {
704	        sirius::op::partition_spec broadcast;
705	        broadcast.mode    = sirius::op::partition_mode::broadcast;
706	        spec.partitioning = std::move(broadcast);
707	      } else if (!impl_->hash_key_columns.empty() && impl_->outputs.size() > 1) {
708	        // key_cast_types left empty; streaming_fragment::build() derives them from the sink's
709	        // own output types (integral keys hash as INT64), so no type names cross the FFI and
710	        // the two ends cannot disagree on a key's width.
711	        sirius::op::partition_spec hash;
712	        hash.mode         = sirius::op::partition_mode::hash;
713	        hash.key_columns  = impl_->hash_key_columns;
714	        spec.partitioning = std::move(hash);
715	      }
716	
717	      impl_->fragment = std::make_unique<sirius::exec::streaming_fragment>(client, std::move(spec));
718	      impl_->fragment->build(impl_->lifecycle->query_id());
719	    }
720	    impl_->built = true;
721	  } catch (...) {
722	    impl_->end_lifecycle();
723	    throw;
724	  }
725	}
