727	std::size_t Fragment::relay_from(Fragment& source,
728	                                 std::uint64_t source_stream_id,
729	                                 std::uint64_t input_stream_id,
730	                                 std::uint32_t sender_id)
731	{
732	  if (!impl_->built) {
733	    throw sirius::invalid_input_exception("Fragment: build() must run before relay_from()");
734	  }
735	
736	  // The drain loop below stops at the first nullopt, which means "nothing right now" as well as
737	  // "ended". Before the source has run, those are indistinguishable, so relaying early would
738	  // close the input after zero batches and silently truncate the result.
739	  if (!source.impl_->ran) {
740	    throw sirius::invalid_input_exception(
741	      "Fragment: relay_from() requires the source fragment to have run — call source.run() first, "
742	      "otherwise an empty stream is indistinguishable from a finished one and the input would be "
743	      "closed early");
744	  }
745	
746	  // The docs promise this throws on an unknown stream id; it used to fall through both guards
747	  // and move batches unchecked.
748	  auto declared_it = impl_->resolved_inputs.find(input_stream_id);
749	  if (declared_it == impl_->resolved_inputs.end()) {
750	    throw sirius::invalid_input_exception("Fragment: relay target input stream " +
751	                                          std::to_string(input_stream_id) +
752	                                          " was never declared on this fragment");
753	  }
754	  if (source.impl_->fragment == nullptr) {
755	    throw sirius::invalid_input_exception(
756	      "Fragment: relay source has no output streams — a result fragment produces Arrow via "
757	      "result_to_arrow(), not a relayable stream");
758	  }
759	
760	  // Schema check: fail before any data moves if column count or types disagree.
761	  {
762	    const auto& declared = declared_it->second.types;
763	    const auto& produced = source.impl_->fragment->sink_types();
764	    if (produced.size() != declared.size()) {
765	      throw sirius::invalid_input_exception(
766	        "Fragment: relay into stream " + std::to_string(input_stream_id) + " expects " +
767	        std::to_string(declared.size()) + " declared columns but the source sink produces " +
768	        std::to_string(produced.size()));
769	    }
770	    for (std::size_t i = 0; i < declared.size(); ++i) {
771	      if (produced[i] != declared[i]) {
772	        throw sirius::invalid_input_exception(
773	          "Fragment: relay into stream " + std::to_string(input_stream_id) + " column " +
774	          std::to_string(i) + " is declared " + declared[i].to_string() +
775	          " but the source sink produces " + produced[i].to_string());
776	      }
777	    }
778	  }
779	
780	  std::size_t moved = 0;
781	  while (auto batch = source.impl_->session().pull(source_stream_id)) {
782	    // Registered before the push so the placement's `queued` precedes the receiver's `packaged`;
783	    // this is where the batch's park on the sender's output stream ends.
784	    telemetry::batch_telemetry_registry::instance().on_stream_hop(
785	      *batch, telemetry::batch_origin::stream_relayed);
786	    if (!impl_->session().push(input_stream_id, *batch)) {
787	      throw sirius::invalid_input_exception("Fragment: input stream " +
788	                                            std::to_string(input_stream_id) +
789	                                            " refused a batch; it had already ended");
790	    }
791	    ++moved;
792	  }
793	  impl_->session().close_input(input_stream_id, sender_id);
794	  return moved;
795	}
