803	std::unique_ptr<std::vector<std::uint8_t>> Fragment::export_packed(std::uint64_t stream_id,
804	                                                                   std::uint64_t& offset,
805	                                                                   std::uint64_t& length,
806	                                                                   std::uint64_t& rows)
807	{
808	  if (!impl_->built) {
809	    throw sirius::invalid_input_exception("Fragment: build() must run before export_packed()");
810	  }
811	  auto& arena = sirius::exec::exchange_staging_arena::require(impl_->ctx.staging_arena.get());
812	
813	  offset     = 0;
814	  length     = 0;
815	  rows       = 0;
816	  auto batch = impl_->session().pull(stream_id);
817	  if (!batch) { return nullptr; }
818	
819	  // The shared lock holds residency and immutability for the whole pack; it releases when this
820	  // scope ends, after the packing stream has been synchronized and the data lives in the lease.
821	  auto read_only = (*batch)->to_read_only();
822	  if (read_only.get_current_tier() != cucascade::memory::Tier::GPU) {
823	    throw sirius::invalid_input_exception(
824	      "Fragment: batch on output stream " + std::to_string(stream_id) +
825	      " is not GPU-resident; exporting a spilled batch is not supported yet");
826	  }
827	  auto view   = sirius::get_cudf_table_view(read_only);
828	  auto* space = read_only.get_memory_space();
829	  if (space == nullptr) {
830	    throw sirius::invalid_input_exception("Fragment: batch on output stream " +
831	                                          std::to_string(stream_id) + " has no memory space");
832	  }
833	  rows = static_cast<std::uint64_t>(view.num_rows());
834	
835	  auto stream = cudf::get_default_stream();
836	  // STREAM-LINEAGE: order the pack's gather after the batch's writer.
837	  if (cudaEvent_t writer = read_only.get_writer_event()) {
838	    if (auto err = cudaStreamWaitEvent(stream.value(), writer, 0); err != cudaSuccess) {
839	      throw sirius::internal_exception("Fragment: cudaStreamWaitEvent failed: {}",
840	                                       cudaGetErrorString(err));
841	    }
842	  }
843	
844	  auto packer =
845	    cudf::chunked_pack::create(view, kPackChunkBytes, stream, space->get_default_allocator());
846	  const std::uint64_t total = packer->get_total_contiguous_size();
847	
848	  // A zero-row batch packs to a metadata-only frame: no payload, no lease. The wire contract
849	  // says offset==0 with length==0 means "no lease exists for this batch", so the receiver never
850	  // releases it — leasing here would orphan kPackChunkBytes of arena per empty batch, and one
851	  // orphaned lease pins staging space for the process lifetime.
852	  if (total == 0) { return packer->build_metadata(); }
853	
854	  // Each next() span is a full chunk long and starts where the previous copy ended, so the
855	  // final span can reach up to one chunk past the payload — hence the slack.
856	  const auto lease_offset = arena.lease(total + kPackChunkBytes);
857	  // GPU pool -> staging lease as a DataBatch in_transit on the lease; a throw below releases
858	  // the lease, which settles and destructs it.
859	  auto* arena_probe = arena.probe();
860	  if (arena_probe != nullptr) {
861	    arena_probe->on_pack_started(lease_offset, space->get_id(), total);
862	  }
863	  std::unique_ptr<std::vector<std::uint8_t>> metadata;
864	  try {
865	    auto* lease         = reinterpret_cast<std::uint8_t*>(arena.base()) + lease_offset;
866	    std::size_t written = 0;
867	    while (packer->has_next()) {
868	      written += packer->next(cudf::device_span<std::uint8_t>(lease + written, kPackChunkBytes));
869	    }
870	    if (written != total) {
871	      throw sirius::internal_exception(
872	        "Fragment: chunked_pack wrote {} of {} bytes for output stream {}",
873	        written,
874	        total,
875	        stream_id);
876	    }
877	    metadata = packer->build_metadata();
878	    // The caller transmits from the lease the moment this returns.
879	    stream.synchronize();
880	    if (arena_probe != nullptr) { arena_probe->on_pack_completed(lease_offset); }
881	  } catch (...) {
882	    arena.release(lease_offset);
883	    throw;
884	  }
885	  offset = lease_offset;
886	  length = total;
887	  return metadata;
888	}
