890	void Fragment::push_packed(std::uint64_t stream_id,
891	                           std::uintptr_t metadata_addr,
892	                           std::size_t metadata_len,
893	                           std::uint64_t offset,
894	                           std::uint64_t length)
895	{
896	  if (!impl_->built) {
897	    throw sirius::invalid_input_exception("Fragment: build() must run before push_packed()");
898	  }
899	  auto& arena = sirius::exec::exchange_staging_arena::require(impl_->ctx.staging_arena.get());
900	  if (metadata_addr == 0 || metadata_len == 0) {
901	    throw sirius::invalid_input_exception("Fragment: push_packed() requires pack metadata");
902	  }
903	  if (offset > arena.capacity() || length > arena.capacity() - offset) {
904	    throw sirius::invalid_input_exception(
905	      "Fragment: push_packed() range [{}, +{}) exceeds the staging arena capacity {}",
906	      offset,
907	      length,
908	      arena.capacity());
909	  }
910	
911	  const auto* metadata = reinterpret_cast<const std::uint8_t*>(metadata_addr);
912	  const auto* payload  = reinterpret_cast<const std::uint8_t*>(arena.base()) + offset;
913	  // Allocates no device memory: the view aliases the lease until the deep copy below.
914	  auto unpacked = cudf::unpack(metadata, payload);
915	
916	  // The engine reads these columns through the schema the stream was declared with; a
917	  // declaration/payload disagreement must be a loud error here, not reinterpreted bits
918	  // downstream. Checked before the deep copy so a bad batch costs no pool memory.
919	  if (auto it = impl_->resolved_inputs.find(stream_id); it != impl_->resolved_inputs.end()) {
920	    const auto& declared = it->second;
921	    if (static_cast<std::size_t>(unpacked.num_columns()) != declared.types.size()) {
922	      throw sirius::invalid_input_exception(
923	        "Fragment: packed batch for stream {} carries {} columns but the stream declares {}",
924	        stream_id,
925	        unpacked.num_columns(),
926	        declared.types.size());
927	    }
928	    for (std::size_t i = 0; i < declared.types.size(); ++i) {
929	      const auto expected = sirius::get_cudf_type(declared.types[i]);
930	      const auto actual   = unpacked.column(static_cast<cudf::size_type>(i)).type();
931	      if (actual != expected) {
932	        throw sirius::invalid_input_exception(
933	          "Fragment: packed batch for stream {} column {} ({}) is declared {} ({}) but "
934	          "carries {}",
935	          stream_id,
936	          i,
937	          declared.names[i],
938	          declared.types[i].to_string(),
939	          cudf::type_to_name(expected),
940	          cudf::type_to_name(actual));
941	      }
942	    }
943	  }
944	
945	  auto* gpu_space = impl_->ctx.context->get_memory_manager().get_memory_space(
946	    cucascade::memory::Tier::GPU, /*device_id=*/0);
947	  if (gpu_space == nullptr) {
948	    throw sirius::internal_exception("Fragment: push_packed() found no GPU memory space");
949	  }
950	
951	  // Copy-out-on-arrival: the batch the engine keeps lives in ordinary pool memory, so the lease
952	  // is reusable the moment this call returns and the batch is fully accounted and spillable
953	  // like any other.
954	  // Staging lease -> GPU pool as a DataBatch in_transit on the lease. A metadata-only frame
955	  // (length == 0) holds no lease, so offset 0 would name someone else's lease: skip it.
956	  auto* arena_probe = length > 0 ? arena.probe() : nullptr;
957	  if (arena_probe != nullptr) {
958	    arena_probe->on_unpack_started(offset, gpu_space->get_id(), length);
959	  }
960	  auto stream = cudf::get_default_stream();
961	  auto table  = std::make_unique<cudf::table>(unpacked, stream, gpu_space->get_default_allocator());
962	  stream.synchronize();
963	  if (arena_probe != nullptr) { arena_probe->on_unpack_completed(offset); }
964	
965	  // A wire batch has no local producing pipeline (nil), but it is a real GPU-resident batch:
966	  // probe it so it appears as a DataBatch, and register the hop so the receiver task's claim
967	  // adopts the placement instead of lazily inventing one.
968	  auto data_batch =
969	    sirius::make_data_batch(std::move(table),
970	                            *gpu_space,
971	                            stream,
972	                            telemetry::batch_telemetry_info{
973	                              impl_->ctx.context->get_telemetry_context().get(), uuid::new_nil()});
974	  telemetry::batch_telemetry_registry::instance().on_stream_hop(
975	    data_batch, telemetry::batch_origin::stream_pushed);
976	  if (!impl_->session().push(stream_id, std::move(data_batch))) {
977	    throw sirius::invalid_input_exception("Fragment: input stream " + std::to_string(stream_id) +
978	                                          " refused a packed batch; it had already ended");
979	  }
980	}
