990	void Fragment::run()
991	{
992	  if (!impl_->built) {
993	    throw sirius::invalid_input_exception("Fragment: build() must run before run()");
994	  }
995	  if (impl_->ran) { throw sirius::invalid_input_exception("Fragment: already run"); }
996	
997	  try {
998	    if (impl_->is_result()) {
999	      auto& client = *impl_->ctx.conn->context;
1000	      sirius::sirius_interface iface(client, impl_->query_label, impl_->session_label);
1001	      impl_->result = iface.sirius_execute_query(client,
1002	                                                 impl_->query_label,
1003	                                                 impl_->result_plan,
1004	                                                 duckdb::PendingQueryParameters{},
1005	                                                 impl_->lifecycle->query_id());
1006	    } else {
1007	      impl_->fragment->run();
1008	    }
1009	    impl_->ran = true;
1010	  } catch (...) {
1011	    // Poison every output before unwinding. Without this the streams are neither closed nor
1012	    // failed, so a peer parked in wait() blocks forever with no error anywhere — the S2/S3
1013	    // hazard the design doc calls out. First-failure-wins, so this cannot mask a real cause.
1014	    // A result fragment has no outputs, so this is a no-op there.
1015	    auto const cause = std::current_exception();
1016	    for (auto id : impl_->outputs) {
1017	      try {
1018	        impl_->session().fail_output(id, cause);
1019	      } catch (...) {  // NOLINT(bugprone-empty-catch)
1020	      }
1021	    }
1022	    impl_->end_lifecycle();
1023	    throw;
1024	  }
1025	  impl_->lifecycle->finish();
1026	  impl_->lifecycle.reset();
1027	  if (impl_->result && impl_->result->HasError()) { impl_->result->ThrowError(); }
1028	}
