1050	std::uint64_t Fragment::output_row_count(std::uint64_t stream_id) const
1051	{
1052	  if (!impl_->fragment) { return 0; }
1053	  const auto& repository = impl_->fragment->output_repository(stream_id);
1054	
1055	  // Non-destructive walk: by-id lookups leave the parked queue intact, unlike session().pull.
1056	  std::uint64_t rows = 0;
1057	  for (std::size_t partition = 0; partition < repository->num_partitions(); ++partition) {
1058	    for (auto batch_id : repository->get_batch_ids(partition)) {
1059	      auto batch = repository->get_data_batch_by_id(batch_id, partition);
1060	      if (!batch) { continue; }  // popped concurrently; parked outputs are quiescent in practice
1061	      auto read_only = batch->to_read_only();
1062	      if (read_only.get_current_tier() != cucascade::memory::Tier::GPU) {
1063	        throw sirius::invalid_input_exception(
1064	          "Fragment: batch on output stream " + std::to_string(stream_id) +
1065	          " is not GPU-resident; counting a spilled batch's rows is not supported yet");
1066	      }
1067	      rows += static_cast<std::uint64_t>(sirius::get_cudf_table_view(read_only).num_rows());
1068	    }
1069	  }
1070	  return rows;
1071	}
