386	/// Translates a flat preorder StarRocks plan into a Substrait relation tree.
387	///
388	/// `root_output_exprs` are the fragment's output expressions (empty when absent); they count
389	/// as consumers sitting above the fragment root for [`common_slots_consumed_above`].
390	pub(crate) fn translate_plan(
391	    plan: &TPlan,
392	    root_output_exprs: &[TExpr],
393	    desc: &DescriptorTable,
394	    scan_paths: &ScanFilePaths,
395	    exchange_inputs: &std::collections::HashMap<i32, &ExchangeInput>,
396	    registry: &mut ExtensionRegistry,
397	) -> Result<TranslatedFragment> {
398	    let mut ctx = PlanContext::new(desc, scan_paths, exchange_inputs, registry);
399	    ctx.exchange_state_overrides = merge_exchange_overrides(plan)?;
400	    ctx.consumed_above = common_slots_consumed_above(plan, root_output_exprs, desc)?;
401	    let root = plan.translate(&mut ctx)?;
402	    if let Some(expansion) = &ctx.partial_expansion {
403	        // Only the fragment root's row leaves this CN by name. Any node above the expanded
404	        // aggregation would resolve the aggregation's slots at their FE positions, which the
405	        // expansion moved -- a wrong column read, not a type error the engine would catch.
406	        if plan.nodes.first().map(|node| node.node_id) != Some(expansion.node_id) {
407	            return Err(TranslateError::UnsupportedPlanNode {
408	                node_id: expansion.node_id,
409	                node_type: TPlanNodeType::AGGREGATION_NODE,
410	                reason: "a partial aggregation over avg must be the fragment root; a node above \
411	                         it reads the aggregate's columns at the positions the avg state moved \
412	                         (SET new_planner_agg_stage = 1)",
413	            });
414	        }
415	        if root.output_width != expansion.names.len() {
416	            return Err(TranslateError::malformed(format!(
417	                "partial aggregation emits {} columns but named {} of them",
418	                root.output_width,
419	                expansion.names.len()
420	            )));
421	        }
422	    }
423	    Ok(TranslatedFragment {
424	        root,
425	        stream_inputs: std::mem::take(&mut ctx.stream_inputs),
426	        partial_expansion: ctx.partial_expansion,
427	    })
428	}
