430	/// Computes the positional wire-column overrides for exchanges that feed merge aggregations.
431	///
432	/// Runs over the flat preorder node list before translation, because the exchange is
433	/// translated before its parent aggregation and must already declare the stream with the
434	/// modeled partial-state columns — their types, and the extra column a wider state (avg)
435	/// occupies. In preorder a merge aggregation's single child is simply the next node; anything
436	/// but an exchange there means the plan reads partial states from a shape this translator
437	/// cannot type, so it is refused.
438	fn merge_exchange_overrides(
439	    plan: &TPlan,
440	) -> Result<std::collections::HashMap<i32, Vec<StateColumns>>> {
441	    let mut overrides = std::collections::HashMap::new();
442	    for (index, node) in plan.nodes.iter().enumerate() {
443	        if node.node_type != TPlanNodeType::AGGREGATION_NODE {
444	            continue;
445	        }
446	        // A node without agg_node fails in translate_aggregation with its own error.
447	        let Some(agg) = node.agg_node.as_ref() else {
448	            continue;
449	        };
450	        if agg_phase::classify(node.node_id, node.node_type, agg)? != AggPhase::Merge {
451	            continue;
452	        }
453	        let child = plan
454	            .nodes
455	            .get(index + 1)
456	            .filter(|child| child.node_type == TPlanNodeType::EXCHANGE_NODE);
457	        if child.is_none() {
458	            return Err(TranslateError::UnsupportedPlanNode {
459	                node_id: node.node_id,
460	                node_type: node.node_type,
461	                reason: "a merge aggregation must read its partial states directly from an \
462	                         exchange (SET new_planner_agg_stage = 1)",
463	            });
464	        }
465	        let keys = agg.grouping_exprs.as_deref().unwrap_or_default().len();
466	        let mut columns = Vec::with_capacity(agg.aggregate_functions.len());
467	        for (position, measure) in agg.aggregate_functions.iter().enumerate() {
468	            // The exchange row is the intermediate tuple's materialized slots: grouping keys
469	            // first, then one state slot per measure -- the same layout invariant the
470	            // aggregation's output tuple uses. A state wider than its slot (avg) claims the
471	            // columns behind it, which is where the partial fragment emitted them.
472	            columns.push(StateColumns {
473	                position: keys + position,
474	                types: partial_state::wire_columns(measure_function(measure)?)?
475	                    .into_iter()
476	                    .map(|column| column.ty)
477	                    .collect(),
478	            });
479	        }
480	        overrides.insert(child.unwrap().node_id, columns);
481	    }
482	    Ok(overrides)
483	}
