485	/// Finds, for every project node, the common-expr slots an ancestor consumes even though no
486	/// output tuple materializes them.
487	///
488	/// StarRocks' BE physically outputs a project's common slots when a node above references
489	/// them, and the FE plans against that; this pre-pass reproduces the FE's view so
490	/// [`translate_project_node`] can widen the project with the consumed columns. One walk over
491	/// the flat preorder node list, keeping the open ancestors on a stack (the same span math
492	/// `PlanNodeCursor` uses): when a `PROJECT_NODE` with a non-empty `common_slot_map` is
493	/// visited, every expression payload of its strict ancestors — plus `root_output_exprs`,
494	/// which sit above the fragment root — is scanned for references to its non-materialized
495	/// common slots. Matching is by slot id alone: new-optimizer slot ids are query-global and an
496	/// ancestor ref can carry a stale tuple id (see `DescriptorTable::slot_global_index`). A
497	/// false positive only widens the row with a column the root confinement drops; a false
498	/// negative leaves today's loud zero-candidate descriptor error. Neither is silent.
499	fn common_slots_consumed_above(
500	    plan: &TPlan,
501	    root_output_exprs: &[TExpr],
502	    desc: &DescriptorTable,
503	) -> Result<std::collections::HashMap<i32, Vec<i32>>> {
504	    let mut consumed = std::collections::HashMap::new();
505	    // Open ancestors of the node being visited: (node index, children not yet completed).
506	    let mut stack: Vec<(usize, i32)> = Vec::new();
507	    for (index, node) in plan.nodes.iter().enumerate() {
508	        if node.node_type == TPlanNodeType::PROJECT_NODE
509	            && let Some(common) = node
510	                .project_node
511	                .as_ref()
512	                .and_then(|project| project.common_slot_map.as_ref())
513	                .filter(|common| !common.is_empty())
514	        {
515	            let mut candidates = std::collections::BTreeSet::new();
516	            for &slot_id in common.keys() {
517	                let mut materialized = false;
518	                for &tuple_id in &node.row_tuples {
519	                    if desc.materialized_slot_ids(tuple_id)?.contains(&slot_id) {
520	                        materialized = true;
521	                        break;
522	                    }
523	                }
524	                if !materialized {
525	                    candidates.insert(slot_id);
526	                }
527	            }
528	            if !candidates.is_empty() {
529	                let mut hits = std::collections::BTreeSet::new();
530	                for &(ancestor, _) in &stack {
531	                    collect_slot_ref_hits(&plan.nodes[ancestor], &candidates, &mut hits);
532	                }
533	                for expr in root_output_exprs {
534	                    collect_expr_slot_ref_hits(expr, &candidates, &mut hits);
535	                }
536	                if !hits.is_empty() {
537	                    consumed.insert(node.node_id, hits.into_iter().collect());
538	                }
539	            }
540	        }
541	        if node.num_children > 0 {
542	            stack.push((index, node.num_children));
543	        } else {
544	            // A leaf completes itself, and possibly the subtrees of the ancestors above it.
545	            while let Some(top) = stack.last_mut() {
546	                top.1 -= 1;
547	                if top.1 == 0 {
548	                    stack.pop();
549	                } else {
550	                    break;
551	                }
552	            }
553	        }
554	    }
555	    Ok(consumed)
556	}
