630	/// Replaces a receiver exchange boundary with a read of the sender's output **stream**.
631	///
632	/// The sender's rows are already on the GPU, parked in the engine as native batches. So the read
633	/// resolves to the engine's stream view rather than to a file: nothing is materialized, nothing
634	/// is re-parsed, and the boundary costs a pointer move. The schema the read declares is also
635	/// recorded on the context, because the engine has no file to infer it from and the fragment must
636	/// declare the same one.
637	fn translate_exchange(
638	    node: &TPlanNode,
639	    children: Vec<TranslatedRel>,
640	    ctx: &mut PlanContext<'_>,
641	) -> Result<TranslatedRel> {
642	    expect_children(node, &children, 0)?;
643	    let exchange = node
644	        .exchange_node
645	        .as_ref()
646	        .ok_or(TranslateError::MissingField {
647	            context: "EXCHANGE_NODE",
648	            field: "exchange_node",
649	        })?;
650	    if exchange.input_row_tuples.is_empty() {
651	        return Err(TranslateError::MissingField {
652	            context: "TExchangeNode",
653	            field: "input_row_tuples",
654	        });
655	    }
656	    let input =
657	        ctx.exchange_inputs
658	            .get(&node.node_id)
659	            .ok_or(TranslateError::UnsupportedPlanNode {
660	                node_id: node.node_id,
661	                node_type: node.node_type,
662	                reason: "exchange node requires a bound same-node input stream",
663	            })?;
664	    let mut schema = ctx
665	        .desc
666	        .named_struct_for_tuples(&exchange.input_row_tuples)?;
667	    // An exchange feeding a merge aggregation carries partial-state columns; rewrite their
668	    // FE-declared slot types to the modeled wire types, and make room for the states the FE
669	    // declares in fewer columns than Sirius ships (avg). One `Type`, two consumers: the
670	    // ReadRel base_schema below and the engine's stream declaration derive from the same
671	    // rewritten entry, so the plan's view of the column and the engine's cannot drift apart.
672	    if let Some(state_overrides) = ctx.exchange_state_overrides.get(&node.node_id) {
673	        let types = schema
674	            .r#struct
675	            .as_mut()
676	            .map(|structure| &mut structure.types)
677	            .ok_or_else(|| TranslateError::malformed("exchange schema has no struct"))?;
678	        let width = types.len();
679	        // Positions index the FE-declared row, so every insertion shifts the ones after it.
680	        let mut inserted = 0usize;
681	        for column in state_overrides {
682	            let position = column.position + inserted;
683	            let slot = types.get_mut(position).ok_or_else(|| {
684	                TranslateError::malformed(format!(
685	                    "merge aggregation state column {} is outside the exchange row \
686	                     ({width} columns)",
687	                    column.position
688	                ))
689	            })?;
690	            *slot = column.types[0].clone();
691	            for (offset, ty) in column.types.iter().enumerate().skip(1) {
692	                types.insert(position + offset, ty.clone());
693	            }
694	            inserted += column.types.len() - 1;
695	        }
696	    }
697	    let output_width = schema
698	        .r#struct
699	        .as_ref()
700	        .map(|structure| structure.types.len())
701	        .unwrap_or(0);
702	    // The stream's columns are the sender's, named by the sender: an expanded state has more
703	    // columns than the receiver's tuple has slots, so the descriptor names cannot name them.
704	    if input.names.len() != output_width {
705	        return Err(TranslateError::descriptor(format!(
706	            "row layout {:?} has {} fields but exchange input has {} names",
707	            exchange.input_row_tuples,
708	            output_width,
709	            input.names.len()
710	        )));
711	    }
712	    schema.names = input.names.clone();
713	
714	    let columns = schema
715	        .names
716	        .iter()
717	        .cloned()
718	        .zip(
719	            schema
720	                .r#struct
721	                .as_ref()
722	                .map(|structure| structure.types.as_slice())
723	                .unwrap_or_default(),
724	        )
725	        .map(|(name, ty)| {
726	            Ok(StreamInputColumn {
727	                name,
728	                ty: crate::type_mapper::duckdb_type_name(ty)?,
729	            })
730	        })
731	        .collect::<Result<Vec<_>>>()?;
732	    ctx.stream_inputs.push(StreamInputSchema {
733	        node_id: node.node_id,
734	        stream_view: input.stream_view.clone(),
735	        columns,
736	    });
737	
738	    let mut translated = TranslatedRel {
739	        rel: stream_read_rel(schema, &input.stream_view),
740	        row_tuples: exchange.input_row_tuples.clone(),
741	        output_width,
742	        // Streams never carry: the sender's root narrowed any carried columns away, and the
743	        // declared stream schema describes exactly the descriptor row.
744	        carried_slots: Vec::new(),
745	    };
746	    if let Some(sort_info) = &exchange.sort_info {
747	        let sorts = sort_fields(sort_info, &translated, ctx)?;
748	        let row_tuples = translated.row_tuples.clone();
749	        translated = TranslatedRel {
750	            rel: Rel {
751	                rel_type: Some(rel::RelType::Sort(Box::new(SortRel {
752	                    input: Some(Box::new(translated.rel)),
753	                    sorts,
754	                    ..Default::default()
755	                }))),
756	            },
757	            row_tuples,
758	            output_width,
759	            carried_slots: Vec::new(),
760	        };
761	    }
762	    apply_conjuncts(translated, node, ctx)
763	}
