246	    /// Translates a fragment with fully materialized inputs for its same-node exchange nodes.
247	    pub fn translate_fragment_with_exchange_inputs(
248	        &self,
249	        params: &TExecPlanFragmentParams,
250	        exchange_inputs: &[ExchangeInput],
251	    ) -> Result<TranslatedPlan> {
252	        let fragment = params
253	            .fragment
254	            .as_ref()
255	            .ok_or(TranslateError::MissingField {
256	                context: "TExecPlanFragmentParams",
257	                field: "fragment",
258	            })?;
259	        let plan = fragment.plan.as_ref().ok_or(TranslateError::MissingField {
260	            context: "TPlanFragment",
261	            field: "plan",
262	        })?;
263	        let desc_tbl = params
264	            .desc_tbl
265	            .as_ref()
266	            .ok_or(TranslateError::MissingField {
267	                context: "TExecPlanFragmentParams",
268	                field: "desc_tbl",
269	            })?;
270	
271	        let desc = DescriptorTable::try_from(desc_tbl)?;
272	        let scan_paths = ScanFilePaths::from_fragment(params, &desc)?;
273	        let exchange_inputs = exchange_inputs
274	            .iter()
275	            .map(|input| (input.node_id, input))
276	            .collect::<HashMap<_, _>>();
277	        let mut registry = ExtensionRegistry::new();
278	        let node_translator::TranslatedFragment {
279	            root: mut translated,
280	            stream_inputs,
281	            partial_expansion,
282	        } = node_translator::translate_plan(
283	            plan,
284	            fragment.output_exprs.as_deref().unwrap_or_default(),
285	            &desc,
286	            &scan_paths,
287	            &exchange_inputs,
288	            &mut registry,
289	        )?;
290	
291	        let output_names = if let Some(output_exprs) = fragment
292	            .output_exprs
293	            .as_ref()
294	            .filter(|output_exprs| !output_exprs.is_empty())
295	        {
296	            if partial_expansion.is_some() {
297	                return Err(TranslateError::malformed(
298	                    "a partial aggregation with an avg state cannot be reprojected by fragment \
299	                     output expressions, which read the aggregate's columns at the positions \
300	                     the state moved (SET new_planner_agg_stage = 1)",
301	                ));
302	            }
303	            let names = output_exprs
304	                .iter()
305	                .enumerate()
306	                .map(|(idx, expr)| {
307	                    output_name_for_expr(expr, &desc).unwrap_or_else(|| format!("expr_{idx}"))
308	                })
309	                .collect::<Vec<_>>();
310	            translated =
311	                node_translator::project_exprs(translated, output_exprs, &desc, &mut registry)?;
312	            names
313	        } else {
314	            // Carried common-expr columns are a fragment-internal mechanism and never leave
315	            // the fragment. Narrow back to the descriptor row BEFORE deriving names: a
316	            // width-preserving root (a SELECT conjunct above the carrying project, say) would
317	            // otherwise ship columns the sender's names and the receiver's declared stream
318	            // schema do not describe. (The output_exprs branch above narrows naturally — its
319	            // root projection emits only the output expressions.)
320	            translated = node_translator::confine_carried(translated);
321	            if let Some(expansion) = &partial_expansion {
322	                // A partial avg ships more columns than the FE's output tuple has slots, so
323	                // the descriptor table cannot name the row. These names are what the receiver
324	                // reads the stream's columns by.
325	                expansion.names.clone()
326	            } else {
327	                desc.output_names_for_tuples(&translated.row_tuples)?
328	            }
329	        };
330	
331	        let output_names = unique_names(output_names).collect::<Vec<_>>();
332	
333	        // One loud guard against any width/name drift at the root: the names are what the
334	        // receiver (or the client) reads the row by, so a mismatch is a wrong column read
335	        // waiting to happen — never ship it.
336	        if output_names.len() != translated.output_width {
337	            return Err(TranslateError::malformed(format!(
338	                "fragment root emits {} columns but derived {} output names",
339	                translated.output_width,
340	                output_names.len()
341	            )));
342	        }
343	
344	        // Resolve a hash-partitioned sink's keys to output column indices while the row layout
345	        // is still in hand. Bare SLOT_REFs only: any transform would make this sender hash a
346	        // value its peers do not, silently splitting equal keys across destinations.
347	        let output_partition_columns = match fragment
348	            .output_sink
349	            .as_ref()
350	            .and_then(|sink| sink.stream_sink.as_ref())
351	            .map(|stream_sink| &stream_sink.output_partition)
352	        {
353	            Some(partition)
354	                if partition.type_
355	                    == starrocks_thrift::partitions::TPartitionType::HASH_PARTITIONED =>
356	            {
357	                if fragment
358	                    .output_exprs
359	                    .as_ref()
360	                    .is_some_and(|exprs| !exprs.is_empty())
361	                {
362	                    return Err(TranslateError::malformed(
363	                        "a hash-partitioned stream sink with output_exprs cannot map its \
364	                         partition keys onto the sink row (never emitted by the FE)",
365	                    ));
366	                }
367	                let exprs = partition.partition_exprs.as_deref().unwrap_or_default();
368	                if exprs.is_empty() {
369	                    return Err(TranslateError::malformed(
370	                        "a hash-partitioned stream sink carries no partition expressions",
371	                    ));
372	                }
373	                let mut columns = Vec::with_capacity(exprs.len());
374	                for expr in exprs {
375	                    let slot_ref = match expr.nodes.as_slice() {
376	                        [node] if node.node_type == TExprNodeType::SLOT_REF => {
377	                            node.slot_ref.as_ref()
378	                        }
379	                        _ => None,
380	                    };
381	                    let Some(slot_ref) = slot_ref else {
382	                        return Err(TranslateError::malformed(
383	                            "a hash-partition key is not a bare slot reference; hashing a \
384	                             transformed key would silently split equal keys across senders",
385	                        ));
386	                    };
387	                    let column = desc.slot_global_index(
388	                        slot_ref.tuple_id,
389	                        slot_ref.slot_id,
390	                        &translated.row_tuples,
391	                    )?;
392	                    // Slot indices come from the FE's tuple, where an expanded avg state
393	                    // occupies one column and the real row has it occupying two. Grouping
394	                    // keys sit ahead of every measure and so keep their index; a partition
395	                    // key that is not one would hash the wrong column.
396	                    if let Some(expansion) = &partial_expansion
397	                        && column >= expansion.keys
398	                    {
399	                        return Err(TranslateError::malformed(
400	                            "a hash-partition key references an aggregate column whose position \
401	                             moved when the avg state expanded \
402	                             (SET new_planner_agg_stage = 1)",
403	                        ));
404	                    }
405	                    columns.push(column);
406	                }
407	                Some(columns)
408	            }
409	            _ => None,
410	        };
411	
412	        let (extension_urns, extensions) = registry.into_extensions();
413	        let substrait_plan = Plan {
414	            // Source the spec version from the `substrait` crate so it tracks the
415	            // generated proto types instead of drifting on dependency bumps (a
416	            // hardcoded literal silently diverges from the crate it describes).
417	            version: Some(substrait::version::version_with_producer(
418	                self.producer.clone(),
419	            )),
420	            extension_urns,
421	            extensions,
422	            relations: vec![PlanRel {
423	                rel_type: Some(plan_rel::RelType::Root(RelRoot {
424	                    input: Some(translated.rel),
425	                    names: output_names.clone(),
426	                })),
427	            }],
428	            ..Default::default()
429	        };
430	
431	        Ok(TranslatedPlan {
432	            plan: substrait_plan,
433	            output_names,
434	            output_partition_columns,
435	            stream_inputs,
436	        })
437	    }
438	}
