86	struct lowered_plan {
87	  duckdb::shared_ptr<duckdb::PreparedStatementData> prepared;
88	  duckdb::unique_ptr<duckdb::LogicalOperator> plan;
89	};
90	
91	lowered_plan lower_substrait(duckdb::Connection& conn, const std::string& substrait_plan)
92	{
93	  auto& client = *conn.context;
94	
95	  // Substrait transformation and planning both bind against the catalog, and every catalog lookup
96	  // goes through TransactionContext::ActiveTransaction(). DuckDB 1.5.5 throws there when no
97	  // transaction is open ("TransactionContext::ActiveTransaction called without active
98	  // transaction"); 1.5.4 tolerated it. Fragment::build() commits its view-creation transaction
99	  // before opening the StandaloneQueryScope, so by the time we are called there is usually none.
100	  //
101	  // Own one only if the caller has not already opened it — the single-shot path in
102	  // execute_substrait() begins its own and expects to still own it on return.
103	  //
104	  // ClientContext::transaction, NOT Connection::BeginTransaction(): the latter runs
105	  // Query("BEGIN TRANSACTION"), an ordinary statement that would take the lifecycle mutex the
106	  // enclosing StandaloneQueryScope already holds.
107	  const bool owned_transaction = !client.transaction.HasActiveTransaction();
108	  if (owned_transaction) { client.transaction.BeginTransaction(); }
109	
110	  try {
111	    // Byte-ranged parquet splits ride the plan's LocalFiles items, but DuckDB's consumer and
112	    // parquet binding cannot carry them — extract into a per-plan state the physical plan
113	    // generator consumes. Always replaced (and removed when this plan has none), so a stale
114	    // registry can never leak a previous plan's ranges into this one.
115	    client.registered_state->Remove(sirius::planner::scan_byte_ranges_state::kStateKey);
116	    if (auto ranges = sirius::planner::extract_scan_byte_ranges(substrait_plan); !ranges.empty()) {
117	      client.registered_state->Insert(
118	        sirius::planner::scan_byte_ranges_state::kStateKey,
119	        duckdb::make_shared_ptr<sirius::planner::scan_byte_ranges_state>(std::move(ranges)));
120	    }
121	
122	    duckdb::SubstraitToDuckDB transformer(conn.context, substrait_plan, /*json=*/false);
123	    auto relation = transformer.TransformPlan();
124	
125	    duckdb::Planner planner(client);
126	    planner.CreatePlan(duckdb::make_uniq<duckdb::RelationStatement>(relation));
127	
128	    auto prepared = duckdb::make_shared_ptr<duckdb::PreparedStatementData>(
129	      duckdb::StatementType::SELECT_STATEMENT);
130	    prepared->names     = planner.names;
131	    prepared->types     = planner.types;
132	    prepared->value_map = std::move(planner.value_map);
133	
134	    auto logical_plan = std::move(planner.plan);
135	    if (client.config.enable_optimizer) {
136	      duckdb::Optimizer optimizer(*planner.binder, client);
137	      logical_plan = optimizer.Optimize(std::move(logical_plan));
138	    }
139	    logical_plan->ResolveOperatorTypes();
140	    duckdb::ColumnBindingResolver resolver;
141	    duckdb::ColumnBindingResolver::Verify(*logical_plan);
142	    resolver.VisitOperator(*logical_plan);
143	
144	    if (owned_transaction) { client.transaction.Commit(); }
145	    return {std::move(prepared), std::move(logical_plan)};
146	  } catch (...) {
147	    if (owned_transaction) { client.transaction.Rollback(nullptr); }
148	    throw;
149	  }
150	}
