154	// PIMPL: holds the engine + embedded DuckDB using DuckDB's own smart pointers
155	// (duckdb::shared_ptr, so the SiriusContext can register as a ClientContextState).
156	struct Context::Impl {
157	  duckdb::shared_ptr<duckdb::SiriusContext> context;
158	  duckdb::unique_ptr<duckdb::DuckDB> db;
159	  duckdb::unique_ptr<duckdb::Connection> conn;
160	  //! stream_bind_catalog: also in registered_state; held here past registered_state resets.
161	  duckdb::shared_ptr<sirius::exec::stream_bind_catalog> stream_catalog;
162	  //! Cross-node exchange staging (opt-in via SIRIUS_EXCHANGE_STAGING_BYTES; null otherwise, and
163	  //! every staging call errors loudly). Plain cudaMalloc by contract — see the arena's header.
164	  //! `shared_ptr` so a `StagingArena` handle can serve leases from other threads (the arena's
165	  //! internal mutex makes that safe) and outlive this context; there is still exactly ONE
166	  //! allocator — the handle shares it, never mirrors it.
167	  std::shared_ptr<sirius::exec::exchange_staging_arena> staging_arena;
168	
169	  void bring_up(sirius::sirius_config& config)
170	  {
171	    // The extension path installs the engine log sink from SiriusContextExtensionCallback's
172	    // ctor, which this FFI path never constructs — leaving SIRIUS_LOG_* dead and every
173	    // engine-side stall invisible on a compute node. Honor the env here, but only when
174	    // explicitly configured, so embedders without SIRIUS_LOG_* keep today's behavior (no
175	    // surprise ./log directory).
176	    const char* log_backend = std::getenv("SIRIUS_LOG_BACKEND");
177	    const char* log_dir     = std::getenv("SIRIUS_LOG_DIR");
178	    const char* log_level   = std::getenv("SIRIUS_LOG_LEVEL");
179	    if (log_backend != nullptr || log_dir != nullptr || log_level != nullptr) {
180	      if (log_backend != nullptr) { duckdb::Config::LOG_BACKEND = log_backend; }
181	      if (log_dir != nullptr) { duckdb::Config::LOG_DIR = log_dir; }
182	      if (log_level != nullptr) { duckdb::Config::LOG_LEVEL = log_level; }
183	      duckdb::install_configured_log_sink(nullptr);
184	    }
185	
186	    context = duckdb::make_shared_ptr<duckdb::SiriusContext>();
187	    context->initialize(config);
188	    // Register the builtin + parquet representation converters the GPU scan/result
189	    // path needs. Idempotent; the transparent path does this at extension load.
190	    sirius::converter_registry::initialize();
191	
192	    // Substrait lowering uses core functions and resolves local_files reads to parquet_scan.
193	    db = duckdb::make_uniq<duckdb::DuckDB>(nullptr);
194	    db->LoadStaticExtension<duckdb::CoreFunctionsExtension>();
195	    db->LoadStaticExtension<duckdb::ParquetExtension>();
196	    conn = duckdb::make_uniq<duckdb::Connection>(*db);
197	    // Register the engine on the connection and disable DuckDB optimizer rewrites this
198	    // no-fallback FFI path cannot safely execute. The transparent path only disables
199	    // IN_CLAUSE and COMPRESSED_MATERIALIZATION here; this path remains more conservative.
200	    auto& client = *conn->context;
201	    client.registered_state->Insert(kSiriusStateKey, context);
202	    // Per-connection Sirius state (guard depths, capture bookkeeping) for the
203	    // embedded connection, mirroring OnConnectionOpened on the transparent path.
204	    client.registered_state->Insert("sirius_connection_state",
205	                                    duckdb::make_shared_ptr<duckdb::SiriusConnectionState>());
206	
207	    // Fragment bind path: register catalog + sirius_stream_source before any plan binds.
208	    stream_catalog = duckdb::make_shared_ptr<sirius::exec::stream_bind_catalog>();
209	    client.registered_state->Insert(sirius::exec::stream_bind_catalog::kStateKey, stream_catalog);
210	    sirius::exec::register_stream_source_function(*db->instance);
211	
212	    // pin_table/unpin_table on the embedded catalog, so Context::pin_table can run
213	    // the same table function the extension registers (same bind, same behavior).
214	    {
215	      auto transaction = duckdb::CatalogTransaction::GetSystemTransaction(*db->instance);
216	      auto& catalog    = duckdb::Catalog::GetSystemCatalog(*db->instance);
217	      duckdb::SiriusExtension::RegisterPinTableFunctions(transaction, catalog);
218	    }
219	
220	    // After engine bring-up so the arena's cudaMalloc comes out of the headroom the operator
221	    // left beside the pool budget, not out of memory the pool then misses.
222	    staging_arena = sirius::exec::exchange_staging_arena::from_env();
223	    if (staging_arena != nullptr) {
224	      // The arena sits outside every cucascade memory space, so the engine's memory_context
225	      // never sees it; give it its own Quent Memory and report leases and pack/unpack transfers
226	      // as DataBatch transitions. Null telemetry context leaves the arena telemetry-free.
227	      if (auto telemetry_context = context->get_telemetry_context()) {
228	        staging_arena->attach_probe(std::make_shared<sirius::telemetry::staging_arena_telemetry>(
229	          std::move(telemetry_context), &context->get_memory_manager(), staging_arena->capacity()));
230	      }
231	    }
232	
233	    client.config.enable_optimizer = true;
234	    auto& disabled = duckdb::DBConfig::GetConfig(client).options.disabled_optimizers;
235	    disabled.insert(duckdb::OptimizerType::IN_CLAUSE);
236	    disabled.insert(duckdb::OptimizerType::COMPRESSED_MATERIALIZATION);
237	    // Keep this FFI-only restriction until its no-fallback execution path has
238	    // dedicated GPU_VALUES coverage.
239	    disabled.insert(duckdb::OptimizerType::STATISTICS_PROPAGATION);
240	    disabled.insert(duckdb::OptimizerType::COLUMN_LIFETIME);
241	    // Rewrites an ORDER BY ... LIMIT parquet scan into a semi-join on virtual
242	    // file_index/file_row_number columns the GPU scan drops.
243	    disabled.insert(duckdb::OptimizerType::LATE_MATERIALIZATION);
244	  }
245	};
