 67	        let Some(exec_params) = params.params.as_ref() else {
 68	            return Ok(paths);
 69	        };
 70	        for (node_id, ranges) in &exec_params.per_node_scan_ranges {
 71	            paths.add_ranges(*node_id, ranges, desc)?;
