 74	            for (node_id, per_seq) in per_driver {
 75	                // A node must appear in exactly one of the two scan-range maps.
 76	                // StarRocks keeps them disjoint (LocalFragmentAssignmentStrategy),
 77	                // but that contract is invisible here, so enforce it locally: a node
 78	                // in both would have its whole-file paths collected — and read —
 79	                // twice, silently duplicating rows.
 80	                if exec_params.per_node_scan_ranges.contains_key(node_id) {
