160	bool BuildProbeSideOptimizer::TryFlipJoinChildren(LogicalOperator &op) const {
161		auto &left_child = *op.children[0];
162		auto &right_child = *op.children[1];
163		const auto lhs_cardinality = left_child.has_estimated_cardinality ? left_child.estimated_cardinality
164		                                                                  : left_child.EstimateCardinality(context);
165		const auto rhs_cardinality = right_child.has_estimated_cardinality ? right_child.estimated_cardinality
166		                                                                   : right_child.EstimateCardinality(context);
167	
168		auto build_sizes = GetBuildSizes(op, lhs_cardinality, rhs_cardinality);
169		auto &left_side_build_cost = build_sizes.left_side;
170		auto &right_side_build_cost = build_sizes.right_side;
171	
172		bool swap = false;
173	
174		idx_t left_child_joins = ChildHasJoins(*op.children[0]);
175		idx_t right_child_joins = ChildHasJoins(*op.children[1]);
176		// if the right child is a table scan, and the left child has joins, we should prefer the left child
177		// to be the build side. Since the tuples of the left side will already have been built on/be in flight,
178		// it will be faster to build on them again.
179		if (right_child_joins == 0 && left_child_joins > 0) {
180			right_side_build_cost *= (1 + PREFER_RIGHT_DEEP_PENALTY);
181		}
182	
183		// RHS is build side.
184		// if right_side metric is larger than left_side metric, then right_side is more costly to build on
185		// than the lhs. So we swap
186		if (right_side_build_cost > left_side_build_cost) {
187			swap = true;
188		}
189	
190		// swap for preferred on probe side
191		if (rhs_cardinality == lhs_cardinality && !preferred_on_probe_side.empty()) {
192			// inspect final bindings, we prefer them on the probe side
193			auto bindings_left = left_child.GetColumnBindings();
194			auto bindings_right = right_child.GetColumnBindings();
195			auto bindings_in_left = ComputeOverlappingBindings(bindings_left, preferred_on_probe_side);
196			auto bindings_in_right = ComputeOverlappingBindings(bindings_right, preferred_on_probe_side);
197			// (if the sides are planning to be swapped AND
198			// if more projected bindings are in the left (meaning right/build side after the swap)
199			// then swap them back. The projected bindings stay in the left/probe side.)
200			// OR
201			// (if the sides are planning not to be swapped AND
202			// if more projected bindings are in the right (meaning right/build)
203			// then swap them. The projected bindings are swapped to the left/probe side.)
204			if ((swap && bindings_in_left > bindings_in_right) || (!swap && bindings_in_right > bindings_in_left)) {
205				swap = !swap;
206			}
207		}
208	
209		if (swap) {
210			FlipChildren(op);
211		}
212		return swap;
213	}
