215	void BuildProbeSideOptimizer::VisitOperator(LogicalOperator &op) {
216		// then the currentoperator
217		switch (op.type) {
218		case LogicalOperatorType::LOGICAL_DELIM_JOIN: {
219			auto &join = op.Cast<LogicalComparisonJoin>();
220			if (HasInverseJoinType(join.join_type)) {
221				join.delim_flipped = TryFlipJoinChildren(join);
222			}
223			break;
224		}
225		case LogicalOperatorType::LOGICAL_COMPARISON_JOIN: {
226			auto &join = op.Cast<LogicalComparisonJoin>();
227			switch (join.join_type) {
228			case JoinType::SEMI:
229			case JoinType::ANTI: {
230				// if the conditions have no equality, do not flip the children.
231				// There is no physical join operator (yet) that can do an inequality right_semi/anti join.
232				idx_t has_range = 0;
233				bool prefer_range_joins = Settings::Get<PreferRangeJoinsSetting>(context);
234				if (op.type == LogicalOperatorType::LOGICAL_ANY_JOIN ||
235				    (op.Cast<LogicalComparisonJoin>().HasEquality(has_range) && !prefer_range_joins)) {
236					TryFlipJoinChildren(join);
237				}
238				break;
239			}
240			default:
241				if (HasInverseJoinType(join.join_type)) {
242					TryFlipJoinChildren(op);
243				}
244			}
245			break;
246		}
247		case LogicalOperatorType::LOGICAL_ANY_JOIN: {
248			auto &join = op.Cast<LogicalJoin>();
249			// We do not yet support the RIGHT_SEMI or RIGHT_ANTI join types for these, so don't try to flip
250			switch (join.join_type) {
251			case JoinType::SEMI:
252			case JoinType::ANTI:
253				break; // RIGHT_SEMI/RIGHT_ANTI not supported yet for ANY/ASOF
254			default:
255				// We cannot flip projection maps are set (YET), but not flipping is worse than just clearing them
256				// They will be set in the 2nd round of ColumnLifetimeAnalyzer
257				join.left_projection_map.clear();
258				join.right_projection_map.clear();
259				TryFlipJoinChildren(op);
260			}
261			break;
262		}
263		case LogicalOperatorType::LOGICAL_CROSS_PRODUCT: {
264			TryFlipJoinChildren(op);
265			break;
266		}
267		default:
268			break;
269		}
